const rawOutput = $input.first().json.output || '';
const telegramInput = $('Telegram Trigger').first().json.message || {};
const chatId = telegramInput.chat?.id;
const messageId = telegramInput.message_id;

// Helper to anchor any date/time strictly to Europe/Berlin
function toBerlinISO(dateTimeStr) {
  if (!dateTimeStr) return '';
  try {
    const clean = dateTimeStr.replace(/Z$/i, '').split('+')[0];
    const dt = DateTime.fromISO(clean, { zone: 'Europe/Berlin' });
    return dt.isValid ? dt.toISO() : dateTimeStr;
  } catch (e) {
    return dateTimeStr;
  }
}

// Helper to get Berlin ISO range for a target date
function getDateRange(dateStr) {
  const target = dateStr || $now.setZone('Europe/Berlin').toFormat('yyyy-MM-dd');
  try {
    const dt = DateTime.fromISO(target, { zone: 'Europe/Berlin' });
    return {
      targetDate: target,
      timeMin: dt.startOf('day').toISO(),
      timeMax: dt.endOf('day').toISO()
    };
  } catch (e) {
    return {
      targetDate: target,
      timeMin: target + 'T00:00:00+02:00',
      timeMax: target + 'T23:59:59+02:00'
    };
  }
}

// Match JSON action block
const actionRegex = /```(?:json:calendar_action|json)\s*([\s\S]*?)\s*```/;
const match = rawOutput.match(actionRegex);

if (match) {
  try {
    const data = JSON.parse(match[1]);
    const cleanMessage = rawOutput.replace(actionRegex, '').trim();
    const action = data.action || 'chat';

    if (action === 'create' && data.summary && data.start) {
      return [{
        json: {
          action: 'create',
          chatId,
          messageId,
          replyText: cleanMessage,
          summary: data.summary,
          start: toBerlinISO(data.start),
          end: toBerlinISO(data.end || data.start),
          description: data.description || '',
          location: data.location || 'Google Meet',
          attendees: Array.isArray(data.attendees) ? data.attendees : []
        }
      }];
    }

    if (action === 'get') {
      const range = getDateRange(data.targetDate);
      return [{
        json: {
          action: 'get',
          chatId,
          messageId,
          targetDate: range.targetDate,
          dateFormatted: data.dateFormatted || range.targetDate,
          timeMin: range.timeMin,
          timeMax: range.timeMax
        }
      }];
    }

    if (action === 'delete') {
      const range = getDateRange(data.targetDate);
      return [{
        json: {
          action: 'delete',
          chatId,
          messageId,
          query: data.query || '',
          targetDate: range.targetDate,
          timeMin: range.timeMin,
          timeMax: range.timeMax
        }
      }];
    }

    if (action === 'update') {
      const range = getDateRange(data.targetDate);
      return [{
        json: {
          action: 'update',
          chatId,
          messageId,
          query: data.query || '',
          newStart: toBerlinISO(data.newStart),
          newEnd: toBerlinISO(data.newEnd || data.newStart),
          targetDate: range.targetDate,
          timeMin: range.timeMin,
          timeMax: range.timeMax
        }
      }];
    }
  } catch (e) {
    // Parsing error fallback
  }
}

// Fallback: conversational reply or asking clarifying questions
return [{
  json: {
    action: 'chat',
    chatId,
    messageId,
    replyText: rawOutput
  }
}];

