const items = $input.all();
let meta = {};
try {
  meta = $('Parse AI Intent & Action').first().json;
} catch (e) {}

let telegramMsg = {};
try {
  telegramMsg = $('Telegram Trigger').first().json.message || {};
} catch (e) {}

const chatId = meta.chatId || telegramMsg.chat?.id;
let dateTitle = meta.dateFormatted || meta.targetDate || 'Selected Date';
const targetDate = meta.targetDate;

try {
  if (targetDate) {
    const dt = DateTime.fromISO(targetDate, { zone: 'Europe/Berlin' });
    if (dt.isValid) {
      dateTitle = dt.toFormat('EEEE, dd MMMM yyyy');
    }
  }
} catch (e) {}

const userText = telegramMsg.text || '';
const isTurkish = /[çğıöşüÇĞİÖŞÜ]|(\b(toplanti|toplantı|bugun|bugün|yarin|yarın|takvim|gun|gün|pazartesi|salı|çarşamba|perşembe|cuma|cumartesi|pazar|var|mi|mı|mu|mü|ne|neler|hangisi)\b)/i.test(userText);

function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const hasValidEvents = items && items.length > 0 && items[0].json && items[0].json.id;

if (!hasValidEvents) {
  const emptyMsg = isTurkish
    ? `📅 <b>${escapeHtml(dateTitle)} için Takviminiz (Berlin Saati):</b>\n\n✨ Bu tarihte planlanmış herhangi bir toplantınız bulunmuyor. Gününüz tamamen boş! 🎉`
    : `📅 <b>Schedule for ${escapeHtml(dateTitle)} (Berlin Time):</b>\n\n✨ You do not have any meetings scheduled on this day. You are completely free! 🎉`;

  return [{
    json: {
      chatId,
      messageText: emptyMsg
    }
  }];
}

let msg = isTurkish
  ? `📅 <b>${escapeHtml(dateTitle)} Toplantılarınız (${items.length} adet) [Berlin Saati]:</b>\n\n`
  : `📅 <b>Meetings on ${escapeHtml(dateTitle)} (${items.length} total) [Berlin Time]:</b>\n\n`;

for (let i = 0; i < items.length; i++) {
  const ev = items[i].json;
  const summary = escapeHtml(ev.summary || (isTurkish ? 'Başlıksız Toplantı' : 'Untitled Event'));
  let timeStr = isTurkish ? 'Tüm Gün' : 'All Day';
  if (ev.start?.dateTime) {
    try {
      const sDt = DateTime.fromISO(ev.start.dateTime).setZone('Europe/Berlin');
      const eDt = ev.end?.dateTime ? DateTime.fromISO(ev.end.dateTime).setZone('Europe/Berlin') : null;
      const s = sDt.toFormat('HH:mm');
      const e = eDt ? eDt.toFormat('HH:mm') : '';
      timeStr = e ? `${s} - ${e} (Berlin)` : `${s} (Berlin)`;
    } catch (err) {
      const s = ev.start.dateTime.substring(11, 16);
      const e = ev.end?.dateTime ? ev.end.dateTime.substring(11, 16) : '';
      timeStr = e ? `${s} - ${e} (Berlin)` : s;
    }
  }

  const loc = ev.location ? ` | 📍 <i>${escapeHtml(ev.location)}</i>` : ' | 📍 <i>Google Meet</i>';
  const linkText = isTurkish ? 'Takvim' : 'Calendar';
  const link = ev.htmlLink ? ` (<a href="${ev.htmlLink}">${linkText}</a>)` : '';

  msg += `${i + 1}. ⏰ <b>${timeStr}</b> — <b>${summary}</b>${loc}${link}\n`;
  if (ev.description) {
    const desc = escapeHtml(ev.description.substring(0, 100));
    msg += `   📝 <i>${desc}</i>\n`;
  }
  msg += `\n`;
}

return [{
  json: {
    chatId,
    messageText: msg
  }
}];

