  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const todayFormatted = $now.setZone('Europe/Berlin').toFormat('EEEE, dd MMMM yyyy');
const chatId = '1519369571';

const hasValidEvents = items && items.length > 0 && items[0].json && items[0].json.id;

if (!hasValidEvents) {
  const emptyReminder = `🔔 <b>Günaydın Serhat! (Berlin Saati)</b>\n\n📅 <i>${escapeHtml(todayFormatted)}</i>\n\n✨ Bugün için takviminizde planlanmış herhangi bir toplantı bulunmuyor. Gününüz tamamen boş! Harika ve verimli bir gün dilerim! 🚀`;
  return [{
    json: {
      hasEvents: false,
      eventCount: 0,
      chatId,
      reminderText: emptyReminder
    }
  }];
}

let reminder = `🔔 <b>Bugünkü Toplantı Özeti (${escapeHtml(todayFormatted)}) [Berlin Saati]</b>\n\n`;
reminder += `Bugün için planlanmış <b>${items.length}</b> adet toplantınız var:\n\n`;

for (let i = 0; i < items.length; i++) {
  const ev = items[i].json;
  const title = escapeHtml(ev.summary || 'Başlıksız Toplantı');
  let timeStr = 'Tüm Gün';
  if (ev.start?.dateTime) {
    try {
      const sDt = DateTime.fromISO(ev.start.dateTime).setZone('Europe/Berlin');
      const eDt = ev.end?.dateTime ? DateTime.fromISO(ev.end.dateTime).setZone('Europe/Berlin') : null;
      const s = sDt.toFormat('HH:mm');
      const e = eDt ? eDt.toFormat('HH:mm') : '';
      timeStr = e ? `${s} - ${e} (Berlin)` : `${s} (Berlin)`;
    } catch (err) {
      const s = ev.start.dateTime.substring(11, 16);
      const e = ev.end?.dateTime ? ev.end.dateTime.substring(11, 16) : '';
      timeStr = e ? `${s} - ${e} (Berlin)` : s;
    }
  }

  const loc = ev.location ? ` | 📍 <i>${escapeHtml(ev.location)}</i>` : ' | 📍 <i>Google Meet</i>';
  const link = ev.htmlLink ? ` (<a href="${ev.htmlLink}">Takvim Bağlantısı</a>)` : '';

  reminder += `${i + 1}. ⏰ <b>${timeStr}</b> — <b>${title}</b>${loc}${link}\n`;
  if (ev.description) {
    reminder += `   📝 <i>${escapeHtml(ev.description.substring(0, 120))}</i>\n`;
  }
  reminder += `\n`;
}

reminder += `Harika ve verimli bir gün dilerim! 🚀`;

return [{
  json: {
    hasEvents: true,
    eventCount: items.length,
    chatId,
    reminderText: reminder
  }
}];
